"""Outcome-blind TRAIN sampling and exact-token handoff inputs for fitting."""

from __future__ import annotations

from dataclasses import asdict, dataclass
import hashlib
from collections.abc import Iterable

from ..trajectory import TaskRef, Trajectory, token_digest, validate_ids


@dataclass(frozen=True)
class HandoffSample:
    task: TaskRef
    trajectory_id: str
    source_model: str
    target_model: str
    tokenizer_id: str
    history_ids: tuple[int, ...]
    query_ids: tuple[int, ...]
    # Query INPUT positions whose next token is generated by the assistant.
    assistant_prediction_positions: tuple[int, ...]
    teacher: str
    truncated: bool = False

    def __post_init__(self):
        if self.task.split != "train":
            raise ValueError("fitting inputs must come from TRAIN")
        for name in ("history_ids", "query_ids", "assistant_prediction_positions"):
            validate_ids(getattr(self, name), name)
        if not self.history_ids or not self.query_ids:
            raise ValueError("handoff fitting needs nonempty history and query")
        positions = self.assistant_prediction_positions
        if tuple(sorted(set(positions))) != positions or any(
            p >= len(self.query_ids) for p in positions
        ):
            raise ValueError("prediction positions must refer to query input tokens")
        if not all(
            (
                self.trajectory_id,
                self.source_model,
                self.target_model,
                self.tokenizer_id,
                self.teacher,
            )
        ):
            raise ValueError("missing fitting provenance")
        if self.source_model == self.target_model:
            raise ValueError("handoff must identify distinct source and target models")

    def to_dict(self) -> dict:
        return dict(
            asdict(self), input_sha256=token_digest(self.history_ids + self.query_ids)
        )


def select_training_trajectories(
    trajectories: Iterable[Trajectory],
    *,
    count: int,
    seed: str,
    excluded_tasks: Iterable[TaskRef] = (),
) -> tuple[Trajectory, ...]:
    """Hash-order complete records, including unsuccessful/limited trajectories.

    One trajectory per task is required. Count refers to attempted tasks, not
    usable handoffs. Excluded identities are explicit; test/dev records reject
    the input bank rather than being silently discarded.
    """
    if type(count) is not int or count <= 0:
        raise ValueError("count must be positive")
    records = tuple(trajectories)
    if any(t.task.split != "train" for t in records):
        raise ValueError("training bank contains dev/test data")
    if len({t.task.key for t in records}) != len(records):
        raise ValueError("duplicate task trajectories would change task weighting")
    excluded = {task.key for task in excluded_tasks}
    available = [t for t in records if t.task.key not in excluded]
    if count > len(available):
        raise ValueError("not enough unique training tasks")
    return tuple(
        sorted(
            available,
            key=lambda t: hashlib.sha256(f"{seed}:{t.task.key}".encode()).hexdigest(),
        )[:count]
    )


def handoff_samples(
    trajectory: Trajectory, *, max_query_tokens: int = 2048
) -> tuple[HandoffSample, ...]:
    """Extract native-teacher continuations at every recorded model switch.

    A backend must expose the handoff prefix even for native re-prefill. Each
    subsequent native target turn must preserve exact prefix token IDs. Mapped
    continuations are rejected as teachers; no retokenization or inferred KV
    residency is used. A switch without a recorded boundary yields no sample.
    """
    if trajectory.task.split != "train":
        raise ValueError("only TRAIN trajectories may produce fitting samples")
    if type(max_query_tokens) is not int or max_query_tokens < 1:
        raise ValueError("query budget must be positive")
    samples = []
    for index, turn in enumerate(trajectory.turns):
        source = turn.cache_plan.source_model
        if not source or source == turn.route.model_id:
            continue
        if (
            index == 0
            or trajectory.turns[index - 1].generation.tokenizer_id
            != turn.generation.tokenizer_id
        ):
            raise ValueError(
                "cross-tokenizer fitting requires an explicit alignment adapter"
            )
        prefix = turn.generation.handoff_prefix_ids
        if not prefix:
            continue
        full = prefix
        positions = []
        H = len(prefix)
        for continuation in trajectory.turns[index:]:
            if continuation.route.model_id != turn.route.model_id:
                break
            gen = continuation.generation
            if gen.executed_mode == "cachebridge":
                raise ValueError("calibration requires native target teachers")
            if (
                gen.tokenizer_id != turn.generation.tokenizer_id
                or gen.prompt_ids[: len(full)] != full
            ):
                raise ValueError(
                    "native continuation changed tokenizer or exact token prefix"
                )
            positions.extend(
                range(
                    max(0, len(gen.prompt_ids) - H - 1),
                    len(gen.prompt_ids) - H + len(gen.completion_ids) - 1,
                )
            )
            full = gen.prompt_ids + gen.completion_ids
        query = full[H : H + max_query_tokens]
        if not query:
            continue
        # Conditional attention-output fitting needs the input activation, not
        # the next-token label. Preserve a prediction at the final input even
        # when its next token lies beyond the truncated calibration window.
        selected = tuple(sorted({p for p in positions if 0 <= p < len(query)}))
        samples.append(
            HandoffSample(
                trajectory.task,
                trajectory.trajectory_id,
                source,
                turn.route.model_id,
                turn.generation.tokenizer_id,
                prefix,
                query,
                selected,
                "native target continuation; no reward or reference-answer filtering",
                truncated=len(full) - H > max_query_tokens,
            )
        )
    return tuple(samples)
